CREATE TABLE IF NOT EXISTS users (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(256) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'cliente',active SMALLINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS dishes (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(130) NOT NULL,description VARCHAR(400) NOT NULL DEFAULT '',category VARCHAR(30) NOT NULL DEFAULT 'Pratos',price DECIMAL(10,2) NOT NULL,image VARCHAR(500) NOT NULL DEFAULT '',active SMALLINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS spaces (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,description VARCHAR(300) NOT NULL DEFAULT '',active SMALLINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS bookings (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,space_id INT NOT NULL,user_id INT NOT NULL,start_at TIMESTAMP NOT NULL,end_at TIMESTAMP NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'confirmada',FOREIGN KEY(space_id) REFERENCES spaces(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS orders (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id INT NOT NULL,name VARCHAR(120) NOT NULL,address VARCHAR(350) NOT NULL,notes VARCHAR(500) NOT NULL DEFAULT '',total DECIMAL(10,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'recebido',courier_id INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(courier_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INT NOT NULL,dish_id INT NOT NULL,name VARCHAR(130) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(dish_id) REFERENCES dishes(id));

CREATE INDEX IF NOT EXISTS bookings_space_dates_idx ON bookings(space_id,start_at,end_at);
